(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-4-anatomical-position-relationships-quiz"]={"title":"Anatomical Position & Relationships — Anatomy Exam 4","category":"Anatomy","sem":"summer-1-2026","questions":[{"q":"In the limbs, the directional term 'proximal' means a structure is located how?","choices":["Nearer to the trunk or point of attachment","Farther from the trunk or attachment","Nearer to the midline of the body","Closer to the surface of the body"],"answer":0,"exp":"Proximal means closer to the trunk of the body or to the point where a limb attaches. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In the limbs, the directional term 'distal' means a structure is located how?","choices":["Nearer to the trunk or attachment","Farther from the body surface","Nearer to the back of the body","Farther from the trunk or point of attachment"],"answer":3,"exp":"Distal means farther from the trunk of the body or from the point where a limb attaches. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the elbow is located how relative to the wrist?","choices":["Proximal to the wrist","Distal to the wrist","Medial to the wrist","Superficial to the wrist"],"answer":0,"exp":"The elbow lies closer to the trunk than the wrist, so it is proximal to the wrist. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the wrist is located how relative to the elbow?","choices":["Proximal to the elbow","Lateral to the elbow","Distal to the elbow","Deep to the elbow"],"answer":2,"exp":"The wrist lies farther from the trunk than the elbow, so it is distal to the elbow. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the radius lies how relative to the ulna?","choices":["Medial to the ulna","Proximal to the ulna","Lateral to the ulna","Deep to the ulna"],"answer":2,"exp":"In anatomical position with the palm forward, the radius is on the thumb (lateral) side, so it is lateral to the ulna. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the ulna lies how relative to the radius?","choices":["Lateral to the radius","Distal to the radius","Superficial to the radius","Medial to the radius"],"answer":3,"exp":"In anatomical position the ulna is on the little-finger (medial) side of the forearm, so it is medial to the radius. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The phalanges of the hand are located how relative to the metacarpals?","choices":["Proximal to the metacarpals","Medial to the metacarpals","Posterior to the metacarpals","Distal to the metacarpals"],"answer":3,"exp":"The finger phalanges lie farther from the wrist than the metacarpals, so they are distal to the metacarpals. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The carpal bones are located how relative to the phalanges?","choices":["Distal to the phalanges","Lateral to the phalanges","Proximal to the phalanges","Deep to the phalanges"],"answer":2,"exp":"The carpal (wrist) bones lie nearer the trunk than the finger phalanges, so they are proximal to the phalanges. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the thumb (pollex) lies how relative to the other fingers?","choices":["Lateral to the other fingers","Medial to the other fingers","Distal to the other fingers","Deep to the other fingers"],"answer":0,"exp":"In anatomical position with the palm forward, the thumb is on the outer (lateral) side of the hand relative to the other fingers. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the knee is located how relative to the ankle?","choices":["Distal to the ankle","Proximal to the ankle","Lateral to the ankle","Posterior to the ankle"],"answer":1,"exp":"The knee lies closer to the trunk than the ankle, so it is proximal to the ankle. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The femur is located how relative to the tibia?","choices":["Distal to the tibia","Medial to the tibia","Proximal to the tibia","Superficial to the tibia"],"answer":2,"exp":"The femur (thigh bone) lies nearer the trunk than the tibia (leg bone), so it is proximal to the tibia. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the tibia lies how relative to the fibula?","choices":["Lateral to the fibula","Distal to the fibula","Medial to the fibula","Deep to the fibula"],"answer":2,"exp":"The tibia is the large bone on the inner (medial) side of the leg, so it is medial to the fibula. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the fibula lies how relative to the tibia?","choices":["Medial to the tibia","Lateral to the tibia","Proximal to the tibia","Anterior to the tibia"],"answer":1,"exp":"The fibula is the slender bone on the outer (lateral) side of the leg, so it is lateral to the tibia. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The metatarsals are located how relative to the tarsal bones?","choices":["Proximal to the tarsals","Medial to the tarsals","Superficial to the tarsals","Distal to the tarsals"],"answer":3,"exp":"The metatarsals lie farther from the ankle than the tarsals, so they are distal to the tarsal bones. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The calcaneus (heel bone) is located how relative to the talus?","choices":["Superior to the talus","Inferior to the talus","Anterior to the talus","Lateral to the talus"],"answer":1,"exp":"The calcaneus sits below the talus, transmitting weight to the ground, so it is inferior to the talus. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'superior' (cranial) means a structure is located how?","choices":["Nearer to the feet","Nearer to the front","Nearer to the midline","Nearer to the head"],"answer":3,"exp":"Superior, or cranial, means toward the head or the upper part of a structure. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'inferior' (caudal) means a structure is located how?","choices":["Nearer to the head","Nearer to the feet","Nearer to the back","Nearer to the surface"],"answer":1,"exp":"Inferior, or caudal, means toward the feet or the lower part of a structure. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The mandible (lower jaw) is located how relative to the frontal bone?","choices":["Superior to the frontal bone","Inferior to the frontal bone","Posterior to the frontal bone","Lateral to the frontal bone"],"answer":1,"exp":"The mandible sits at the bottom of the face, below the frontal bone of the forehead, so it is inferior to the frontal bone. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The frontal bone is located how relative to the occipital bone?","choices":["Posterior to the occipital bone","Inferior to the occipital bone","Anterior to the occipital bone","Medial to the occipital bone"],"answer":2,"exp":"The frontal bone forms the forehead at the front of the skull, while the occipital bone forms the back, so the frontal bone is anterior to the occipital bone. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The cervical vertebrae are located how relative to the thoracic vertebrae?","choices":["Inferior to the thoracic vertebrae","Superior to the thoracic vertebrae","Anterior to the thoracic vertebrae","Lateral to the thoracic vertebrae"],"answer":1,"exp":"The cervical vertebrae of the neck lie above the thoracic vertebrae, so they are superior to the thoracic vertebrae. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The lumbar vertebrae are located how relative to the sacrum?","choices":["Superior to the sacrum","Inferior to the sacrum","Posterior to the sacrum","Deep to the sacrum"],"answer":0,"exp":"The lumbar vertebrae lie above the sacrum in the lower back, so they are superior to the sacrum. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The sternum is located how relative to the thoracic vertebrae?","choices":["Posterior to the thoracic vertebrae","Anterior to the thoracic vertebrae","Superior to the thoracic vertebrae","Lateral to the thoracic vertebrae"],"answer":1,"exp":"The sternum lies at the front of the chest while the thoracic vertebrae lie at the back, so the sternum is anterior to the thoracic vertebrae. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The manubrium is located how relative to the body of the sternum?","choices":["Inferior to the body of the sternum","Anterior to the body of the sternum","Deep to the body of the sternum","Superior to the body of the sternum"],"answer":3,"exp":"The manubrium is the upper region of the sternum, so it lies superior to the body of the sternum. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The xiphoid process is located how relative to the manubrium?","choices":["Inferior to the manubrium","Superior to the manubrium","Lateral to the manubrium","Posterior to the manubrium"],"answer":0,"exp":"The xiphoid process is the lowest part of the sternum, so it lies inferior to the manubrium at the top. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The scapula is located how relative to the rib cage?","choices":["Anterior to the rib cage","Inferior to the rib cage","Medial to the rib cage","Posterior to the rib cage"],"answer":3,"exp":"The scapula lies against the back of the thorax, so it is posterior to the rib cage. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The clavicle is located how relative to the scapula's spine?","choices":["Anterior to the scapular spine","Posterior to the scapular spine","Inferior to the scapular spine","Deep to the scapular spine"],"answer":0,"exp":"The clavicle lies across the front of the shoulder, while the scapular spine is on the back, so the clavicle is anterior to the scapular spine. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'superficial' means a structure is located how?","choices":["Nearer to the body surface","Nearer to the body's core","Nearer to the head","Nearer to the midline"],"answer":0,"exp":"Superficial means closer to the surface of the body. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'deep' means a structure is located how?","choices":["Closer to the body surface","Farther from the body surface","Closer to the feet","Closer to the front"],"answer":1,"exp":"Deep means farther from the surface, toward the interior of the body. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The biceps brachii is located how relative to the humerus?","choices":["Deep to the humerus","Medial to the humerus","Superficial to the humerus","Distal to the humerus"],"answer":2,"exp":"The biceps brachii lies at the surface of the anterior arm, over the humerus, so it is superficial to the humerus. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The sternum is located how relative to the lateral parts of the ribs?","choices":["Medial to the ribs","Lateral to the ribs","Posterior to the ribs","Distal to the ribs"],"answer":0,"exp":"The sternum lies in the midline at the front of the chest, so it is medial to the laterally curving ribs. — Directional & positional terminology applied to Anatomy Exam 4 structures"}]};
